CREATE TABLE account (id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES account(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), timezone TEXT NOT NULL DEFAULT 'Europe/Sofia', emergency_contact TEXT NOT NULL DEFAULT '', emergency_location TEXT NOT NULL DEFAULT '');
INSERT INTO settings(id) VALUES(1);
CREATE TABLE locations (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, country TEXT NOT NULL, form TEXT, route TEXT, ingredient_text TEXT, identity_confirmed INTEGER NOT NULL CHECK(identity_confirmed IN(0,1)), prescription_status TEXT NOT NULL DEFAULT 'unknown' CHECK(prescription_status IN('unknown','otc','prescription')));
CREATE TABLE ingredients (product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, name TEXT NOT NULL, strength TEXT, unit TEXT, basis TEXT, PRIMARY KEY(product_id,ordinal));
CREATE TABLE source_facts (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, official_url TEXT NOT NULL, revision TEXT NOT NULL, provenance TEXT NOT NULL, review_status TEXT NOT NULL CHECK(review_status IN('unreviewed','reviewed')), facts_json TEXT NOT NULL, after_opening_days INTEGER CHECK(after_opening_days>0), expiry_convention TEXT CHECK(expiry_convention='month_end'));
CREATE TABLE packs (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), quantity REAL NOT NULL CHECK(quantity>=0), unit TEXT NOT NULL, location_id TEXT REFERENCES locations(id) ON DELETE SET NULL, expiry_value TEXT, expiry_precision TEXT NOT NULL CHECK(expiry_precision IN('day','month','unknown')), expiry_text TEXT, batch TEXT, opened_date TEXT, storage_uncertain INTEGER NOT NULL CHECK(storage_uncertain IN(0,1)), notes TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN(0,1)), created_at TEXT NOT NULL, CHECK((expiry_precision='unknown' AND expiry_value IS NULL) OR (expiry_precision!='unknown' AND expiry_value IS NOT NULL)));
CREATE INDEX packs_product ON packs(product_id);
CREATE INDEX packs_active_expiry ON packs(archived,expiry_value);
CREATE TABLE purchases (pack_id TEXT PRIMARY KEY REFERENCES packs(id) ON DELETE CASCADE, purchase_date TEXT, pharmacy TEXT, purchased_packs REAL, unit_price REAL, line_total REAL, currency TEXT);
CREATE TABLE import_drafts (id TEXT PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES account(id), mode TEXT NOT NULL CHECK(mode IN('medicine','receipt')), extraction_json TEXT, expires_at INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN('processing','ready','cancelled','confirmed')), fingerprint TEXT, decisions_json TEXT, result_json TEXT, created_at TEXT NOT NULL);
CREATE INDEX imports_expiration ON import_drafts(status,expires_at);
CREATE TABLE import_consumptions (id TEXT PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES account(id), mode TEXT NOT NULL, fingerprint TEXT, pack_ids_json TEXT NOT NULL, confirmed_at TEXT NOT NULL);
